"""Small native source-to-surface/longwave coupling and legacy-isolation check."""
import argparse,copy,json,os,subprocess
from pathlib import Path
import numpy as np


def fixture(root,power):
    root.mkdir(parents=True,exist_ok=False)
    # Native Y-up: a hot plate faces a separate receiver; an extra soil boundary
    # is generated by the normal project loader.
    (root/'world.obj').write_text('g hot\nv -0.5 1.5 -0.5\nv 0.5 1.5 -0.5\nv 0.5 1.5 0.5\nv -0.5 1.5 0.5\nf 1 3 2\nf 1 4 3\ng receiver\nv -1.5 0.1 -1.5\nv 1.5 0.1 -1.5\nv 1.5 0.1 1.5\nv -1.5 0.1 1.5\nf 5 7 6\nf 5 8 7\n',encoding='utf-8')
    (root/'position.txt').write_text('3 3 0 1 0\n',encoding='utf-8')
    (root/'weather.txt').write_text('4\n'+''.join(f'{180.5+i*10/86400:.10f} 26.85 15 1013.25 1 0 {5.670374419e-8*300**4:.8f}\n' for i in range(4)),encoding='utf-8')
    names=['hot','receiver'];spectra=[dict(name=n,model='custom',reflectance='0.2',transmittance='0',refTir=.05,tauTir=0) for n in names]
    core=dict(group='prop',capacityJPerK=1000,conductanceWPerK=100,airConductanceWPerK=0,powerW=power,startSeconds=0,stopSeconds=20,initialK=300,weight=1)
    materials=[dict(name=n,type='Building',energyModel='solid',params=dict(heatCapacityPerArea=1000,convectiveScale=1,**({'lumpedThermal':core} if n=='hot' else {}))) for n in names]
    materials.append(dict(name='soil_boundary',type='Soil',params=dict(rss=1e9,cs=1800,rhos=1600,lambdas=1,SMC=.01)))
    config=dict(scene=dict(x=6,y=6,height=4,voxel=10,terrain=False,background=dict(spectralName='receiver',thermalName='receiver',materialName='soil_boundary',materialType='Soil',heterogeneityEnabled=False)),
        sensor=dict(x=8,y=8,bands='10000',image=False,temperature=True,process=True,energyProcess=True,radiationProcess=False,principalPlane=False,hemisphere=False),
        control=dict(samples=8,depth=4,facetBackend='gpu',couplingIterations=100,temperatureTolerance=.05,temperatureRelaxation=.5,radiationSolver='traditional',spectralAccelerationWidth=128,soilTemperatureMethod=2,stabilityCorrection=False),
        meteo=dict(path=str(root/'weather.txt'),start=0,end=4,dTime=10,timeStepSeconds=[10]*4,Tsold=300,z=10,latitude=40,longitude=120,timezone=8,year=2019),
        light=dict(zenith=30,azimuth=180,direct=.8,diffuse=.2,skyTemperature=300),atmosphere=dict(enabled=False),fluid=dict(enabled=False),spectra=spectra,materials=materials,
        thermals=[dict(name=n,sunlitTemperature=300,shadedTemperature=300) for n in names],canopies=[dict(name='solid',structureType='solid',leafwidth=2)],
        objects=dict(count=1,names=['world'],items=[dict(name='world',type='Building',fileName=str(root/'world.obj'),positionFile=str(root/'position.txt'),meshes=[dict(name=n,spectralName=n,thermalName=n,materialName=n,canopyName='solid') for n in names])]))
    p=root/'project.json';p.write_text(json.dumps(dict(format='histream-project',schemaVersion=1,mode='eFacetEB',configuration=config)),encoding='utf-8');return p


def run(engine,root,power):
    project=fixture(root,power)
    with (root/'native.log').open('wb') as log:
        r=subprocess.run([str(engine),'eFacetEB',str(project),str(root/'output/faceteb.json')],stdout=log,stderr=subprocess.STDOUT,env=dict(os.environ,HISTREAM_FACET_RASTER_LAYERS='64',HISTREAM_FACET_ENERGY_BACKEND='cpu'))
    assert r.returncode==0,(r.returncode,(root/'native.log').read_text(encoding='utf-8',errors='replace')[-1800:])
    index=json.loads((root/'output/faceteb_run.json').read_text(encoding='utf-8'))
    assert index['status']=='completed',index.get('status')
    assert len(index.get('lumpedThermalBodies',[]))==1,'Native coupled thermal body missing'
    diagnostics=[json.loads(p.read_text()) for p in sorted((root/'output/diagnostics').glob('*.json'))]
    assert len(diagnostics)==4,'Missing coupling diagnostics'
    return index,diagnostics


def main():
    p=argparse.ArgumentParser();p.add_argument('engine',type=Path);p.add_argument('output',type=Path);a=p.parse_args()
    a.output.mkdir(parents=True,exist_ok=False)
    on,od=run(a.engine,a.output/'on',2000)
    off,fd=run(a.engine,a.output/'off',0)
    assert od[0]['lumpedThermal'][0]['coreTemperature_K']>fd[0]['lumpedThermal'][0]['coreTemperature_K']+.1
    assert od[0]['lumpedThermal'][0]['conductedToSkin_W']>0
    for d in od+fd:
        assert d['lumpedThermalMaxCoreResidual_W']<1e-5,d
        assert d['lumpedThermalMaxSurfaceResidual_W_m2']<2,d
        assert d['lumpedThermalMaxExchangeMismatch_W']<1e-4,d
    assert od[2]['lumpedThermal'][0]['inputPower_W']==0
    def temperatures(root,index):
        token=index['completed'][-1]['token']
        raw=np.fromfile(root/'output/.facet_steps'/('energy_T='+token+'.bin'),dtype='<f4').reshape(-1,2,13)
        return raw[:,0,0]
    delta=temperatures(a.output/'on',on)-temperatures(a.output/'off',off)
    assert delta[2:4].max()>1e-3,('No longwave response at separate receiver',delta)
    print(json.dumps(dict(status='passed',checks=6,receiverMaxDeltaK=float(delta[2:4].max()),onExecution=on['execution']),ensure_ascii=False))


if __name__=='__main__':main()
